function letterCombinations(digits: string): string[] {
  // Пустой ввод — нет ни одной комбинации (в старой версии задачи такое было)
  if (digits.length === 0) return [];

  // Буквы на кнопках телефона
  const letters: Record<string, string> = {
    '2': 'abc',
    '3': 'def',
    '4': 'ghi',
    '5': 'jkl',
    '6': 'mno',
    '7': 'pqrs',
    '8': 'tuv',
    '9': 'wxyz',
  };

  const result: string[] = [];
  const path: string[] = [];

  // i — индекс цифры, для которой выбираем букву
  const backtrack = (i: number): void => {
    // Выбрали букву для каждой цифры — комбинация готова
    if (i === digits.length) {
      result.push(path.join(''));
      return;
    }
    for (const ch of letters[digits[i]]) {
      path.push(ch); // выбор
      backtrack(i + 1); // следующая цифра
      path.pop(); // откат
    }
  };

  backtrack(0);
  return result;
}

// Время: O(4^n · n) — до 4 букв на цифру, n — длина digits; n на сборку строки
// Память: O(n) на рекурсию и путь (без учёта ответа)
